import React, {useEffect, useRef, useState} from 'react';
import {
  ActivityIndicator,
  StyleProp,
  Text,
  TextInput,
  TextStyle,
  TouchableOpacity,
  View,
} from 'react-native';
import {
  Dropdown,
  IDropdownRef,
  IMultiSelectRef,
  MultiSelect,
} from 'react-native-element-dropdown';
import styles from './styles';
import TextCM from '../Text';
import Color from '../../../constants/Color';
import {CheckBox} from '@ui-kitten/components';
import useDebounce from '../../../hooks/useDebounce';
import {useFetchRequest} from '../../../hooks/useFetch';
import {IconClear} from '../../../assets/images';

type PropCallAPI = {
  url: string;
  method: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
  body: any;
  params: any;
};

type Props = {
  label?: string;
  labelStyle?: StyleProp<TextStyle>;
  isRequired?: boolean;
  disabled?: boolean;
  isCallAPI?: boolean;
  propsCallAPI?: PropCallAPI;
  onBlur?: () => void;
  isError?: boolean;
  modeSelect?: 'single' | 'multi';
  placeholder?: string;
  searchPlaceholder?: string;
  search?: boolean;
  onChange?: (data: any) => void;
  singleValue?: string;
  listValue?: string[];
  listDataProps?: any[];
  maxHeight?: number;
  funcGetData?: (params: any, textSearch?: string) => Promise<any>;
};

const DropDownPickerCM = ({
  label = 'quangnh39',
  labelStyle,
  isRequired = false,
  disabled = false,
  isCallAPI = false,
  propsCallAPI,
  onBlur,
  isError,
  modeSelect = 'single',
  placeholder,
  searchPlaceholder = 'Search ...',
  search = false,
  onChange,
  singleValue,
  listValue,
  listDataProps,
  maxHeight = 300,
  funcGetData,
}: Props) => {
  const [value, setValue] = useState(singleValue);
  const [valueMulti, setValueMulti] = useState<string[] | undefined>(listValue);
  const [isFocus, setIsFocus] = useState(false);
  const [valueSearch, setValueSearch] = useState('');
  const valueSearchDebounce = useDebounce(valueSearch, 500);
  const [isLoading, setIsLoading] = useState(false);
  const [isLoadMore, setIsLoadMore] = useState(false);
  const [page, setPage] = useState(0);
  const [totalPage, setTotalPage] = useState(0);
  const [refresh, setRefresh] = useState(false);
  const [listData, setListData] = useState<any[]>(listDataProps || []);
  const ref = useRef<IDropdownRef>(null);
  const refMulti = useRef<IMultiSelectRef>(null);
  const fetchRequest = useFetchRequest();

  useEffect(() => {
    if (isCallAPI) {
      handleValueSearch();
    }
  }, [valueSearchDebounce]);

  const handleValueSearch = async () => {
    setPage(0);
    await callApi(0, false);
  };

  const handleOnRefresh = () => {
    setRefresh(true);
    callApi(0, false);
    setPage(0);
  };

  const handleLoadMore = async () => {
    if (page < totalPage) {
      await callApi(page + 1, true);
      setPage(page + 1);
    }
  };

  const callApi = async (page: number, isLoadMore: boolean) => {
    try {
      if (isLoadMore) {
        setIsLoadMore(true);
      } else {
        setIsLoading(true);
      }
      const params = {
        page: page,
        size: 10,
        ...propsCallAPI?.params,
      };

      // const response = await fetchRequest({
      //   url: propsCallAPI?.url || '',
      //   method: propsCallAPI?.method || 'POST',
      //   body: JSON.stringify({
      //     ...propsCallAPI?.body,
      //     q: valueSearchDebounce,
      //   }),
      //   params: params,
      // });

      const response = await funcGetData?.(params, valueSearchDebounce);

      if (response) {
        if (page === 0) {
          setListData(
            response?.data?.map((u: any) => ({
              ...u,
              label: u?.email,
              value: u?.email,
            })),
          );
          setTotalPage(Math.ceil(Number(response?.totalRecords) / 10));
        } else {
          setListData([
            ...listData,
            ...response?.data?.map((u: any) => ({
              ...u,
              label: u?.email,
              value: u?.email,
            })),
          ]);
        }
      }
    } catch (error) {
    } finally {
      setIsLoading(false);
      setIsLoadMore(false);
      setRefresh(false);
    }
  };
  function sleep(ms: any) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
  const updateChecked = (value?: string, checked?: boolean) => {
    setListData(prevData => {
      if (modeSelect === 'multi') {
        const index = prevData.findIndex(item => item.value === value);
        if (index === -1) return prevData;

        const newData = [...prevData];
        newData[index] = {...newData[index], checked};
        const listDataSelect = newData
          ?.filter(d => d.checked === true)
          ?.map(d => d.value);
        setValueMulti(listDataSelect);
        onChange?.(listDataSelect);
        return newData;
      } else {
        // Single-select: Set selected one to true, rest to false
        setValue(checked ? (value as any) : null);
        onChange?.(checked ? (value as any) : null);

        return prevData.map(item => ({
          ...item,
          checked: item.value === value ? checked : false,
        }));
      }
    });
    setIsFocus(false);
    ref?.current?.close();
  };

  const renderItem = (item: any) => {
    return (
      <CheckBox
        style={{
          padding: 10,
        }}
        checked={item.checked}
        children={(props: any) => <TextCM {...props}>{item?.label}</TextCM>}
        onChange={checked => updateChecked(item.value, checked)}
      />
    );
  };

  const renderSelectItem = (item: any) => {
    return (
      <TouchableOpacity
        onPress={() => updateChecked(item?.value, false)}
        style={styles.ctnSelectItem}>
        <TextCM numberOfLines={1} style={styles.txtSelectItem}>
          {item?.label}
        </TextCM>
        <IconClear width={12} height={12} />
      </TouchableOpacity>
    );
  };

  const renderHeaderComponent = () => {
    if (!listData?.length && !isLoading) {
      return <RenderEmpty />;
    }

    if (isLoading && !refresh) {
      return <RenderFooter isLoadMore={true} />;
    }
  };

  const handleSearch = (text: string, onSearch: any) => {
    if (!isCallAPI) {
      onSearch(text);
    }
    setValueSearch(text);
  };

  const renderSearchInput = (onSearch: any) => {
    return (
      <View style={styles.inputSearchStyle}>
        <TextInput
          placeholder={searchPlaceholder}
          style={{flex: 1}}
          allowFontScaling={false}
          placeholderTextColor={Color.Text}
          value={valueSearch}
          onChangeText={text => handleSearch(text, onSearch)}
        />
        {valueSearch && (
          <TouchableOpacity onPress={() => handleSearch('', onSearch)}>
            <IconClear width={12} height={12} />
          </TouchableOpacity>
        )}
      </View>
    );
  };

  return (
    <>
      <View>
        {label && (
          <TextCM style={[labelStyle, styles.label]}>
            {label}{' '}
            {isRequired && <TextCM style={{color: '#E14337'}}>*</TextCM>}
          </TextCM>
        )}
        {modeSelect === 'single' && (
          <Dropdown
            ref={ref}
            disable={disabled}
            style={[
              styles.dropdown,
              isFocus && {borderColor: '#055FA4'},
              isError && styles.isError,
              disabled && styles.disable,
            ]}
            maxHeight={maxHeight}
            placeholderStyle={styles.placeholderStyle}
            selectedTextStyle={styles.selectedTextStyle}
            selectedTextProps={{allowFontScaling: false}}
            inputSearchStyle={styles.inputSearchStyle}
            containerStyle={styles.containerStyle}
            itemTextStyle={styles.itemTextStyle}
            iconStyle={styles.iconStyle}
            data={listData}
            search={search}
            renderInputSearch={renderSearchInput}
            labelField="label"
            valueField="value"
            placeholder={!isFocus ? placeholder : '...'}
            searchPlaceholder={searchPlaceholder}
            value={value}
            onFocus={() => setIsFocus(true)}
            onBlur={() => {
              setIsFocus(false);
              onBlur?.();
            }}
            onChange={item => {}}
            autoScroll={false}
            renderItem={renderItem}
            flatListProps={
              isCallAPI
                ? {
                    onEndReachedThreshold: 0.5,
                    ListFooterComponent: (
                      <RenderFooter isLoadMore={isLoadMore} />
                    ),
                    refreshing: refresh,
                    onRefresh: handleOnRefresh,
                    onEndReached: handleLoadMore,
                    ListHeaderComponent: renderHeaderComponent,
                  }
                : {
                    ListHeaderComponent: renderHeaderComponent,
                  }
            }
          />
        )}

        {modeSelect === 'multi' && (
          <MultiSelect
            inside
            ref={refMulti}
            style={[
              styles.dropdown,
              isFocus && {borderColor: '#055FA4'},
              isError && styles.isError,
              disabled && styles.disable,
            ]}
            maxHeight={maxHeight}
            placeholderStyle={styles.placeholderStyle}
            selectedTextStyle={styles.selectedTextStyle}
            selectedTextProps={{allowFontScaling: false}}
            inputSearchStyle={styles.inputSearchStyle}
            containerStyle={styles.containerStyle}
            itemTextStyle={styles.itemTextStyle}
            iconStyle={styles.iconStyle}
            search={search}
            data={listData}
            labelField="label"
            valueField="value"
            placeholder={placeholder}
            renderInputSearch={renderSearchInput}
            searchPlaceholder={searchPlaceholder}
            value={valueMulti}
            onFocus={() => setIsFocus(true)}
            onBlur={() => {
              setIsFocus(false);
              onBlur?.();
            }}
            onChange={item => {
              console.log(item);
            }}
            renderItem={renderItem}
            flatListProps={
              isCallAPI
                ? {
                    onEndReachedThreshold: 0.5,
                    ListFooterComponent: (
                      <RenderFooter isLoadMore={isLoadMore} />
                    ),
                    refreshing: refresh,
                    onRefresh: handleOnRefresh,
                    onEndReached: handleLoadMore,
                    ListHeaderComponent: renderHeaderComponent,
                  }
                : {
                    ListHeaderComponent: renderHeaderComponent,
                  }
            }
            mode="default"
            renderSelectedItem={renderSelectItem}
          />
        )}
      </View>
    </>
  );
};

const RenderEmpty = () => {
  return (
    <View style={styles.emptyContainer}>
      <Text>List Empty!</Text>
    </View>
  );
};

const RenderFooter = ({isLoadMore}: {isLoadMore: boolean}) => {
  if (!isLoadMore) {
    return null;
  }
  return (
    <View style={styles.footerContainer}>
      <ActivityIndicator color={'#055FA4'} size={'small'} />
    </View>
  );
};

export default DropDownPickerCM;
