import {StyleSheet, TouchableOpacity, View} from 'react-native';
import {useState} from 'react';
import {Icon} from '@ui-kitten/components';
import {useTranslation} from 'react-i18next';
import {Color, Font} from '../../../../../../../constants';
import TextCM from '../../../../../../components/Text';
import {CommonUtils} from '../../../../../../../utils';
import ExpandListFile from '../listFileExpand';
type Props = {
  item: any;
};

const FileItem = ({item}: Props) => {
  const {t} = useTranslation();

  const [isExpand, setIsExpand] = useState(false);
  const toggleExpand = () => setIsExpand(!isExpand);

  return (
    <View key={item.id}>
      <TouchableOpacity
        style={styles.documentItem}
        onPress={() => toggleExpand()}>
        <View style={styles.documentRow}>
          <View style={styles.iconTitleContainer}>
            <View style={styles.iconContainer}>
              <Icon
                name={isExpand ? 'chevron-down' : 'chevron-right'}
                fill={'#C83A1B'}
                width={12}
                height={12}
              />
            </View>
            <TextCM numberOfLines={1} style={styles.documentTitle}>
              {CommonUtils.truncateText(item?.fileName, 25)}
            </TextCM>
          </View>
        </View>
      </TouchableOpacity>
      {isExpand && <ExpandListFile item={item} />}
    </View>
  );
};
export default FileItem;

const styles = StyleSheet.create({
  documentItem: {
    paddingVertical: 12,
  },
  documentRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
  },
  iconTitleContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    flex: 1,
    columnGap: 8,
  },
  iconContainer: {
    borderWidth: 1,
    width: 14,
    height: 14,
    borderColor: '#C83A1B',
    borderRadius: 30,
    justifyContent: 'center',
    alignItems: 'center',
  },
  documentTitle: {
    fontSize: 13,
    fontFamily: Font.InterMedium500,
    color: '#00204DE5',
    flex: 1,
  },
  trashIcon: {
    padding: 4,
  },
});
