import {Icon, IndexPath} from '@ui-kitten/components';
import React, {useState} from 'react';
import {ScrollView, TouchableOpacity, View} from 'react-native';
import DropdownListCM from '../../../../components/DropDownList';
import {useTranslation} from 'react-i18next';
import {Color, Font} from '../../../../../constants';
import TextCM from '../../../../components/Text';
import {listStatusFlow, listStatusRequest} from './helper';
import Toast from 'react-native-toast-message';
import InputDate from '../../../../screen/my-receipt/component/modal-filter/InputDate';
import {ValueFilterSearch} from '../zustand/store';
import DropDownPickerCM from '../../../../components/DropdownPicker';
import {getConfig} from '../../../../../services/httpClient';
import {useAccountInfoServices} from '../../../../../hooks/apiHooks/useAccountInfoServices';
import HeaderCM from '../../../../components/Header/HeaderCM';
type Props = {
  onClose: () => void;
  handleSubmitFilter?: () => void;
  setValueFilterSearch: React.Dispatch<
    React.SetStateAction<ValueFilterSearch | undefined>
  >;
  valueFilterSearch?: ValueFilterSearch;
};
const ModalFilter = ({
  handleSubmitFilter,
  setValueFilterSearch,
  valueFilterSearch,
  onClose,
}: Props) => {
  const {t} = useTranslation();
  // const {listTypeReceipt} = useReceiptZustandStore();
  const [valueFilterSearchState, setValueFilterSearchState] = useState<
    ValueFilterSearch | undefined
  >(valueFilterSearch);

  const AccountService = useAccountInfoServices();

  const onChangeStartDate = (value: string | null) => {
    const newStart = value ? new Date(value) : undefined;
    const {endDate} = valueFilterSearch?.rangeDay ?? {};
    if (endDate && newStart && newStart > endDate) {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('BLDT.start_date_not_greater_than_end_date'),
      });
      return;
    }

    setValueFilterSearchState({
      ...valueFilterSearchState,
      rangeDay: {
        ...valueFilterSearchState?.rangeDay,
        startDate: newStart,
      },
    });
  };
  const onChangeEndDate = (value: string | null) => {
    // const today = new Date();
    // today.setHours(0, 0, 0, 0);
    const newEnd = value ? new Date(value) : undefined;
    // if (newEnd && newEnd > today) {
    //   Toast.show({
    //     type: 'error',
    //     text1: t('CM.noti'),
    //     text2: 'Ngày kết thúc không được lớn hơn ngày hôm nay.',
    //   });
    //   return;
    // }
    const {startDate} = valueFilterSearchState?.rangeDay ?? {};
    if (startDate && newEnd && newEnd < startDate) {
      Toast.show({
        type: 'error',
        text1: t('CM.not'),
        text2: t('BLDT.end_date_not_less_than_start_date'),
      });
      return;
    }
    setValueFilterSearchState({
      ...valueFilterSearchState,
      rangeDay: {...valueFilterSearchState?.rangeDay, endDate: newEnd},
    });
  };

  const handleClear = () => {
    setValueFilterSearchState(undefined);
  };

  const handleSubmit = () => {
    setValueFilterSearch(valueFilterSearchState);
    handleSubmitFilter?.();
  };

  const handleGetUser = async (paramsProps?: any, textSearch?: string) => {
    try {
      const params = {
        ...paramsProps,
      };
      const dataFilter = {
        q: textSearch,
      };
      const data = await AccountService.getListAccount(dataFilter, params);
      return data;
    } catch (error) {}
  };

  return (
    <View style={{backgroundColor: '#fff', flex: 1}}>
      <HeaderCM
        title={t('BLDT.filter')}
        style={{backgroundColor: '#fff'}}
        contentStyle={{backgroundColor: '#fff'}}
        titleStyle={{color: Color.Black}}
        fillIconBackLeft={Color.Black}
        onPressIconLeft={onClose}
      />
      <ScrollView style={{flex: 1, paddingHorizontal: 16}}>
        <View style={{marginVertical: 4}}>
          <TextCM
            style={{
              marginVertical: 8,
              fontFamily: Font.InterMedium500,
              fontSize: 14,
            }}>
            {t('Người tạo')}
          </TextCM>
          <DropDownPickerCM
            label=""
            placeholder="Chọn người yêu cầu"
            modeSelect="multi"
            listDataProps={listStatusRequest}
            isCallAPI
            search={true}
            // propsCallAPI={{
            //   url:
            //     getConfig().BASE_URL + '/services/uaa/api/search/user-info/role',
            //   method: 'POST',
            //   params: {role: true},
            //   body: {
            //     advanced: true,
            //     contactId: '',
            //     custId: null,
            //     resourceIds: null,
            //     logins: null,
            //     field: '',
            //     from: '',
            //     ids: [],
            //     keyWord: '',
            //     orgIn: null,
            //     owner: '',
            //     q: '',
            //     recipientId: '',
            //     recipientRole: [],
            //     refId: '',
            //     resource: 'table_user',
            //     terms: {},
            //     to: '',
            //     block: false,
            //   },
            // }}
            funcGetData={handleGetUser}
          />
          {/* <DropdownListCM
          onSelect={(item: IndexPath[]) => {
            setValueFilterSearchState({...valueFilterSearchState, type: item});
          }}
          valueSelect={valueFilterSearchState?.type}
          placeholder={t('Chọn người yêu cầu')}
          multiple={true}
          listData={[]}
          // listData={listTypeReceipt}
        /> */}
        </View>
        <View style={{marginVertical: 4}}>
          <TextCM
            style={{
              marginVertical: 8,
              fontFamily: Font.InterMedium500,
              fontSize: 14,
            }}>
            {t('Trạng thái yêu cầu')}
          </TextCM>
          {/* <DropdownListCM
          onSelect={(item: IndexPath[]) => {
            setValueFilterSearchState({
              ...valueFilterSearchState,
              paymentMethod: item,
            });
          }}
          valueSelect={valueFilterSearchState?.paymentMethod}
          placeholder={t('Chọn trạng thái yêu cầu')}
          multiple={true}
          listData={listStatusRequest}
          isi18n={true}
        /> */}

          <DropDownPickerCM
            label=""
            placeholder="Chọn trạng thái yêu cầu"
            modeSelect="multi"
            listDataProps={listStatusRequest}
          />
        </View>
        <View style={{marginVertical: 4}}>
          <TextCM
            style={{
              marginVertical: 8,
              fontFamily: Font.InterMedium500,
              fontSize: 14,
            }}>
            {t('Trạng thái quy trình')}
          </TextCM>
          {/* <DropdownListCM
          onSelect={(item: IndexPath[]) => {
            setValueFilterSearchState({
              ...valueFilterSearchState,
              status: item,
            });
          }}
          valueSelect={valueFilterSearchState?.status}
          placeholder={t('Chọn trạng thái quy trình')}
          multiple={true}
          listData={listStatusFlow}
          isi18n={true}
        /> */}
          <DropDownPickerCM
            label=""
            placeholder="Chọn trạng thái quy trình"
            modeSelect="multi"
            listDataProps={listStatusFlow}
            maxHeight={200}
          />
        </View>

        <View style={{marginVertical: 4, marginBottom: 12}}>
          <TextCM
            style={{
              marginVertical: 8,
              fontFamily: Font.InterMedium500,
              fontSize: 14,
            }}>
            {t('HM.createDate')}
          </TextCM>
          <View
            style={{
              flexDirection: 'row',
              justifyContent: 'space-between',
              alignItems: 'center',
              marginTop: 10,
              columnGap: 8,
            }}>
            <InputDate
              containerStyle={{flex: 1}}
              value={valueFilterSearchState?.rangeDay?.startDate || null}
              onChangeDate={value => {
                onChangeStartDate(value);
              }}
              maxDate={new Date()}
              disabled={false}
            />
            <Icon name="arrow-forward-outline" width={20} height={20} />
            <InputDate
              containerStyle={{flex: 1}}
              value={valueFilterSearchState?.rangeDay?.endDate || null}
              onChangeDate={value => {
                onChangeEndDate(value);
              }}
              maxDate={new Date()}
              disabled={false}
            />
          </View>
        </View>
      </ScrollView>
      <View
        style={{
          flexDirection: 'row',
          justifyContent: 'space-evenly',
          alignItems: 'center',
          gap: 16,
          marginHorizontal: 16,
        }}>
        <TouchableOpacity
          onPress={handleClear}
          style={{
            flex: 1,
            padding: 12,
            backgroundColor: '#E8F5FF',
            borderRadius: 8,
          }}>
          <TextCM style={{color: '#055FA4', textAlign: 'center'}}>
            {t('DB.filter.set-default')}
          </TextCM>
        </TouchableOpacity>
        <TouchableOpacity
          onPress={handleSubmit}
          style={{
            flex: 1,
            padding: 12,
            backgroundColor: '#055FA4',
            borderRadius: 8,
          }}>
          <TextCM style={{color: '#fff', textAlign: 'center'}}>
            {t('BLDT.filter')}
          </TextCM>
        </TouchableOpacity>
      </View>
    </View>
  );
};

export default ModalFilter;
