import {
  FlatList,
  ImageBackground,
  Pressable,
  TouchableOpacity,
  ScrollView,
  View,
} from 'react-native';
import styles from './styles';
import {IconPlus} from '../../../../../assets/images';
import TextCM from '../../../../components/Text';
import {Color, Font, NavigationName} from '../../../../../constants';
import BottomSheetCM from '../../../../components/BottomSheet';
import CreateNewScreen from '../../../../screen/create-new';
import {useTranslation} from 'react-i18next';
import {useState} from 'react';
import {ListAction, TypeListAction} from './helper';
import {useNavigation} from '@react-navigation/native';

const Body = () => {
  const {t} = useTranslation();
  const navigation = useNavigation<any>();
  const [isShowCreate, setIsShowCreate] = useState(false);

  const handleAction = (id: TypeListAction) => {
    switch (id) {
      case 'create':
        setIsShowCreate(true);
        break;
      case 'receiptOfMine':
        navigation.navigate(NavigationName.DYCScreen, {type: id});
        break;
      case 'receiptOfUnit':
        navigation.navigate(NavigationName.DYCScreen, {type: id});
        break;
      case 'manageReceipt':
        navigation.navigate(NavigationName.BA_QD_SCREEN, {
          type: 'mine',
        });
        break;
      case 'manageReceiptOfUnit':
        navigation.navigate(NavigationName.BA_QD_SCREEN, {
          type: 'unit',
        });
        break;
    }
  };

  return (
    <View style={styles.container}>
      <ImageBackground
        source={{
          uri: 'https://res.cloudinary.com/de0sqyhr9/image/upload/v1749312713/494820910_1374601680485702_5588186593691982135_n_s3t6qu.jpg',
        }}
        style={styles.banner}></ImageBackground>

      <ScrollView
        scrollEnabled={false}
        contentContainerStyle={{
          flexDirection: 'row',
          justifyContent: 'flex-start',
          alignItems: 'flex-start',
          gap: 16,
          flexWrap: 'wrap',
        }}>
        {ListAction.map((item, index) => (
          <View
            style={{
              alignItems: 'center',
              justifyContent: 'center',
              rowGap: 8,
              maxWidth: 80,
            }}>
            <Pressable
              onPress={() => handleAction(item.id)}
              style={styles.icon}>
              {item.icon}
            </Pressable>

            <TextCM
              style={{
                fontFamily: Font.InterMedium500,
                fontSize: 12,
                color: Color.Text,
                textAlign: 'center',
              }}>
              {item.name}
            </TextCM>
          </View>
        ))}
      </ScrollView>

      <BottomSheetCM
        onClose={() => setIsShowCreate(false)}
        isVisible={isShowCreate}
        renderContent={
          <CreateNewScreen onClose={() => setIsShowCreate(false)} />
        }
        title={t('GS.history.createNew')}
      />
    </View>
  );
};

export default Body;
