import React from 'react';
import {useTranslation} from 'react-i18next';
import {formatNumber} from './helper';
import styles from './styles';
import {TouchableOpacity, View} from 'react-native';
import {useNavigation} from '@react-navigation/native';
import TextCM from '../../../../components/Text';
import {INumberReceipt} from '../../../../screen/dashboard';

type ItemType = {
  title: string;
  value: number;
  bgColor: string;
  textColor: string;
};

type Props = {
  numberReceipt: INumberReceipt;
};

const OverviewDocument = ({numberReceipt}: Props) => {
  const navigation = useNavigation<any>();
  const {t} = useTranslation();

  const data = [
    {
      title: 'BLDT.processing_receipt',
      value: numberReceipt.numberReceiptProcessing,
      bgColor: '#ECEFFE',
      textColor: '#0673C6',
    },
    {
      title: 'BLDT.error_receipt',
      value: numberReceipt.numberNumberingReceipt,
      bgColor: '#FEF4E6',
      textColor: '#E18308',
    },
    {
      title: 'BLDT.release',
      value: numberReceipt.numberReceiptReleased,
      bgColor: '#E8F7EF',
      textColor: '#39AC6D',
    },
  ];

  const renderItem = (item: ItemType) => {
    return (
      <TouchableOpacity
        onPress={() => {
          onPressItem(item);
        }}
        key={item.title}
        style={[
          styles.viewItem,
          {
            backgroundColor: item.bgColor,
          },
        ]}>
        <TextCM
          style={[
            styles.txtValue,
            {
              color: item.textColor,
            },
          ]}>
          {formatNumber(item.value)}
        </TextCM>
        <TextCM
          style={[
            styles.txtName,
            {
              color: item.textColor,
            },
          ]}>
          {t(item.title)}
        </TextCM>
      </TouchableOpacity>
    );
  };

  const onPressItem = (item: ItemType) => {
    // switch (item.title) {
    //   case t('HM.TxtPending'):
    //     break;
    //   case t('HM.TxtWaitingResponse'):
    //     break;
    //   case t('HM.TxtExpire'):
    //     break;
    // }
  };

  return (
    <View style={styles.container}>
      <TextCM style={styles.txtTitle}>{t('BLDT.receipt_overview')}</TextCM>
      <View style={styles.viewBody}>{data.map(renderItem)}</View>
    </View>
  );
};

export default OverviewDocument;
