import {Platform, TouchableOpacity, View} from 'react-native';
import {IReceiptItem} from '../../../../../model/interface/receipt.interface';
import TextCM from '../../../../components/Text';
import {Color, Font, NavigationName} from '../../../../../constants';
import Svg, {Ellipse, Line} from 'react-native-svg';
import {useEffect, useRef, useState} from 'react';
import {DateUtils} from '../../../../../utils';
import styles from './styles';
import {useTranslation} from 'react-i18next';
import {useNavigation} from '@react-navigation/native';
import ModalFullScreen from '../../../../components/ModalFullScreen';
import ListContract from '../list-contract';
import {ListStatusFlow} from '../../../interface/status.interface';
type Props = {
  receipt: IReceiptItem;
};

const ReceiptItem = ({receipt}: Props) => {
  const {t} = useTranslation();
  const navigation = useNavigation<any>();
  const [widthOfCard, setWidthOfCard] = useState(0);
  const [isShowListContract, setIsShowListContract] = useState(false);
  const data = receipt?.data;

  const navigateToDetailReceiptScreen = (id: string) => {
    navigation.navigate(NavigationName.BA_QDDetailScreen);
  };

  const DashLine = () => {
    return (
      <Svg height="10" width={'100%'} style={styles.dashLine}>
        <Ellipse cx="0" cy="5" rx="10" ry="4" fill="#f9fafe" />
        <Ellipse cx={'100%'} cy="5" rx="10" ry="4" fill="#f9fafe" />
        <Line
          x1="20"
          y1="5"
          x2={widthOfCard - 20}
          y2="5"
          stroke="#cbcbcb"
          strokeWidth="1"
          strokeDasharray="8.8"
        />
      </Svg>
    );
  };

  const StatusTag = ({
    status,
    type,
  }: {
    status: string;
    type: 'DEFAULT' | 'REQUEST' | 'MIX';
  }) => {
    let properties;
    if (type === 'DEFAULT') {
      properties = ListStatusFlow.find((item: any) => item.value === status);
    }
    if (properties) {
      return (
        <View style={{flex: 1, flexDirection: 'row'}}>
          <View style={{flex: 1}} />
          <View
            style={[
              styles.statusTag,
              {backgroundColor: properties?.bgColor || '#EF5DA81A'},
            ]}>
            <TextCM
              style={[
                styles.statusText,
                {color: properties?.color || '#d94936'},
              ]}>
              {t(`BLDT.${properties?.value}`)}
            </TextCM>
          </View>
        </View>
      );
    }
    return (
      <View style={{flexDirection: 'row', flex: 1}}>
        <View style={{flex: 1}} />
        <View style={[styles.statusTag, {backgroundColor: '#EF5DA81A'}]}>
          <TextCM style={[styles.statusText, {color: '#d94936'}]}>
            {t(`BLDT.${status}`)}
          </TextCM>
        </View>
      </View>
    );
  };

  return (
    <>
      <TouchableOpacity
        onPress={() => navigateToDetailReceiptScreen(data?.id)}
        activeOpacity={Platform.OS === 'ios' ? 0.8 : 0.9}
        style={styles.container}>
        <View
          onLayout={event => {
            const {width} = event.nativeEvent.layout;
            setWidthOfCard(width);
          }}
          style={[
            styles.card,
            styles.radiusTop,
            styles.shadowTop,
            styles.shadowLeft,
            styles.shadowRight,
          ]}>
          <View style={styles.header}>
            <View style={{flex: 1, columnGap: 8}}>
              <TextCM style={styles.title}>
                {'[Số định danh] - [Ngày yêu cầu]'}
              </TextCM>
              <TextCM style={styles.idNumber}>
                {data?.caseCode || 'HN.2024.1002'}
              </TextCM>
            </View>
            <TouchableOpacity
              onPress={() => setIsShowListContract(true)}
              style={[styles.capSoStyle]}>
              <TextCM
                style={{color: Color.White, fontFamily: Font.InterMedium500}}>
                {t('BLDT.arithmetic')}
              </TextCM>
            </TouchableOpacity>
          </View>
        </View>

        <DashLine />

        <View
          style={[
            styles.card,
            styles.radiusBot,
            styles.shadowBottom,
            styles.shadowLeft,
            styles.shadowRight,
          ]}>
          <View style={styles.receiptTypeSection}>
            <View style={styles.lableCardWrap}>
              <TextCM style={styles.receiptTypeLabel}>
                {t('BLDT.type_receipt')}
              </TextCM>
            </View>
            <View style={{flex: 1}}>
              <TextCM style={styles.receiptTypeCode}>
                {data?.type || '---'}
              </TextCM>
            </View>
          </View>

          <View style={styles.dateSection}>
            <View style={styles.lableCardWrap}>
              <TextCM style={styles.dateLabel}>{t('CM.createDateCard')}</TextCM>
            </View>
            <TextCM style={styles.dateValue}>
              {DateUtils.convertDateToDDMMYYYY_H_M(data?.createdDate) || '---'}
            </TextCM>
          </View>

          <View style={styles.statusSection}>
            <View style={styles.lableCardWrap}>
              <TextCM style={styles.statusLabel}>
                {t('Trạng thái yêu cầu')}
              </TextCM>
            </View>
            <StatusTag status={data?.flowStatus} type={'REQUEST'} />
          </View>
          <View style={styles.statusSection}>
            <View style={styles.lableCardWrap}>
              <TextCM style={styles.statusLabel}>
                {t('Trạng thái quy trình')}
              </TextCM>
            </View>
            <StatusTag status={data?.status} type={'DEFAULT'} />
          </View>
        </View>
      </TouchableOpacity>

      <ModalFullScreen
        backdropStyle={{backgroundColor: '#fff'}}
        isVisible={isShowListContract}
        children={<ListContract onClose={() => setIsShowListContract(false)} />}
      />
    </>
  );
};

export default ReceiptItem;
